-- 023: enlaces de boletines OGDH-UPTC en su noticia + noticia Tour Violeta 2026 (Direccion de la Mujer). Idempotente.
SET NAMES utf8mb4;

UPDATE news SET body = CONCAT(body, '<h3>Boletines anuales del OGDH – UPTC</h3><ul><li><a href="https://www.uptc.edu.co/sitio/export/sites/default/portal/sitios/universidad/vic_aca/vic_acad/obs_gen/doc/2025_4boletin.pdf" target="_blank" rel="noopener">Boletín 4 – 2025</a></li><li><a href="https://www.uptc.edu.co/sitio/export/sites/default/portal/sitios/universidad/vic_aca/vic_acad/obs_gen/doc/2024_bolet_3.pdf" target="_blank" rel="noopener">Boletín 3 – 2024</a></li><li><a href="https://www.uptc.edu.co/sitio/export/sites/default/portal/sitios/universidad/vic_aca/vic_acad/obs_gen/doc/2023_bolet_2.pdf" target="_blank" rel="noopener">Boletín 2 – 2023</a></li><li><a href="https://www.uptc.edu.co/sitio/export/sites/default/portal/sitios/universidad/vic_aca/vic_acad/obs_gen/doc/2022_bolet_1.pdf" target="_blank" rel="noopener">Boletín 1 – 2022</a></li></ul>') WHERE slug='ogdh-uptc-ojo-al-dato-violeta-2025' AND body NOT LIKE '%2025_4boletin.pdf%';

INSERT INTO news (observatory_id, title, slug, summary, body, source, image_url, published_at, content_status, created_by)
SELECT (SELECT id FROM observatories WHERE slug='genero' LIMIT 1), 'Tour Violeta 2026: cronograma de jornadas municipales y Encuentros Provinciales de la Dirección de la Mujer', 'tour-violeta-2026-cronograma-direccion-mujer', 'La Dirección de la Mujer e Inclusión Social comparte el cronograma 2026 del Tour Violeta en 18 municipios y el de los Encuentros Provinciales con los Consejos Consultivos de Mujeres.', '<p>La Dirección de la Mujer e Inclusión Social de la Gobernación de Boyacá compartió con el Observatorio de Asuntos de Género el cronograma 2026 del <strong>Tour Violeta</strong>, las jornadas territoriales que la Dirección adelanta municipio por municipio, junto con el cronograma de los <strong>Encuentros Provinciales</strong> con los Consejos Consultivos de Mujeres.</p><p><img src="uploads/cms/2026/09/tour-violeta-cronograma-2026.jpg" alt="Cronograma Tour Violeta 2026"></p><h3>Cronograma Tour Violeta 2026</h3><ul><li><strong>Ventaquemada</strong> – 12/03/2026</li><li><strong>Toguí</strong> – 19/03/2026</li><li><strong>Chiquinquirá</strong> – 9/04/2026</li><li><strong>Turmequé</strong> – 23/04/2026</li><li><strong>Santana</strong> – 7/05/2026</li><li><strong>San Luis de Gaceno</strong> – 11/06/2026</li><li><strong>Villa de Leyva</strong> – 18/06/2026</li><li><strong>Aquitania</strong> – 2/07/2026</li><li><strong>Tunja</strong> – 16/07/2026</li><li><strong>Páez</strong> – 30/07/2026</li><li><strong>Nobsa</strong> – 13/08/2026</li><li><strong>San Pablo de Borbur</strong> – 27/08/2026</li><li><strong>Moniquirá</strong> – 10/09/2026</li><li><strong>Sogamoso</strong> – 24/09/2026</li><li><strong>Samacá</strong> – 8/10/2026</li><li><strong>Santa Rosa de Viterbo</strong> – 22/10/2026</li><li><strong>San José de Pare</strong> – 5/11/2026</li><li><strong>Siachoque</strong> – 19/11/2026</li></ul><h3>Encuentros Provinciales</h3><p>Objetivo: fortalecer las capacidades organizativas, técnicas y participativas de las mujeres del departamento mediante encuentros provinciales orientados a brindar asistencia técnica a los Consejos Consultivos de Mujeres, clarificando su objetivo y finalidad, y desarrollar procesos de capacitación que contribuyan al ejercicio efectivo de sus derechos, la incidencia en la gestión pública y el fortalecimiento del liderazgo femenino en el territorio.</p><p><a href="uploads/cms/2026/09/encuentros-provinciales-cronograma-2026.pdf" target="_blank" rel="noopener">Descargar el cronograma de Encuentros Provinciales (PDF)</a></p><p><em>Fuente: Dirección de la Mujer e Inclusión Social – Gobernación de Boyacá (mayo de 2026).</em></p>', 'Dirección de la Mujer e Inclusión Social – Gobernación de Boyacá', 'uploads/cms/2026/09/tour-violeta-cronograma-2026.jpg', NOW(), 'published', NULL
WHERE NOT EXISTS (SELECT 1 FROM news WHERE slug='tour-violeta-2026-cronograma-direccion-mujer');
